SourceCode.Declaration:
/// <summary>
/// A handheld menu: a named, ordered list of app modules and sub-menus (HSMobileOpsMenuLine),
/// like a mobile device menu in Warehouse management. The default menu is the handheld's Home
/// for every worker without a menu of their own (HSMobileOpsUser.MenuId). With no menus at all
/// the app keeps its plain list of modules.
/// </summary>
public class HSMobileOpsMenu extends common
{
}

Method.Source:
public static HSMobileOpsMenu find(str _menuId, boolean _forUpdate = false)
{
    HSMobileOpsMenu menu;

    if (_menuId)
    {
        menu.selectForUpdate(_forUpdate);
        select firstOnly menu
            where menu.MenuId == _menuId;
    }
    return menu;
}

public static HSMobileOpsMenu findRecId(RefRecId _recId)
{
    HSMobileOpsMenu menu;

    if (_recId)
    {
        select firstOnly menu
            where menu.RecId == _recId;
    }
    return menu;
}

/// <summary>
/// The menu a worker without a menu of their own sees.
/// </summary>
public static HSMobileOpsMenu findDefault()
{
    HSMobileOpsMenu menu;

    select firstOnly menu
        where menu.IsDefault == NoYes::Yes;
    return menu;
}

public void insert()
{
    ttsbegin;
    super();
    if (this.IsDefault)
    {
        HSMobileOpsMenu::clearOtherDefaults(this.RecId);
    }
    ttscommit;
}

public void update()
{
    ttsbegin;
    super();
    if (this.IsDefault)
    {
        HSMobileOpsMenu::clearOtherDefaults(this.RecId);
    }
    ttscommit;
}

/// <summary>
/// Only one menu is the default: setting it on one clears it from the rest.
/// </summary>
private static void clearOtherDefaults(RefRecId _keepRecId)
{
    HSMobileOpsMenu menu;

    menu.skipDataMethods(true);
    update_recordset menu
        setting IsDefault = NoYes::No
        where menu.IsDefault == NoYes::Yes
           && menu.RecId     != _keepRecId;
}

/// <summary>
/// A menu still opened from another menu, or assigned to a worker, can't be deleted - the
/// handheld would lose that branch without anyone noticing.
/// </summary>
public boolean validateDelete()
{
    HSMobileOpsMenuLine line;
    HSMobileOpsUser     user;
    boolean             ok = super();

    if (ok)
    {
        select firstOnly RecId from line
            where line.LineType  == HSMobileOpsMenuLineType::SubMenu
               && line.SubMenuId == this.MenuId;
        if (line.RecId)
        {
            ok = checkFailed(strFmt('Menu %1 is a sub-menu of another menu. Remove it from that menu first.', this.MenuId));
        }
        select firstOnly RecId from user
            where user.MenuId == this.MenuId;
        if (user.RecId)
        {
            ok = checkFailed(strFmt('Menu %1 is assigned to mobile device users. Change their menu first.', this.MenuId));
        }
    }
    return ok;
}

public void delete()
{
    HSMobileOpsMenuLine line;

    ttsbegin;
    delete_from line
        where line.MenuRecId == this.RecId;
    super();
    ttscommit;
}
